import React from "react";
import { Link } from "react-router-dom";
import "./searchResults.css";
import "bootstrap/dist/css/bootstrap.css";

// 搜索结果
export class Results extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      google_results: [],
      show_google_results: null,
      searchResultError: null,
      currentInput: "",
    };
  }

  // 提取搜索结果
  retrieveSearchResults(input) {
    console.log("Start to retrieve search results\n\n");
    fetch(
      "https://api.valueserp.com/search?api_key=14B8F9A0B37D47B28EA28097092BE1EB&q=" +
        input +
        "&google_domain=google.ca&location=Ottawa,Ontario,Canada&gl=ca&hl=en"
    )
      .then((res) => res.json())
      .then(
        (result) => {
          console.log(result);
          this.setState({
            google_results: result.organic_results,
            currentInput: input,
            show_google_results: true,
          });
        },
        (searchResultError) => {
          this.setState({ searchResultError });
        }
      );
  }

  filterGoogleResults = () => {
    // if (this.state.show_google_results === "true") {
    // }

    alert("success");
  };

  render() {
    // 检测数据提取是否存在错误
    let { searchResultError } = this.state;
    if (searchResultError) {
      return <div>Error: {searchResultError.message}</div>;
    }
    let {history} = this.props;
    if(!history){
      throw new Error
    }
    let { input } = this.props.history.location;
    let { google_results } = this.state;
    if (!input) {
      // 不存在输入值
      return <React.Fragment />;
    } else if (input !== this.state.currentInput) {
      // 存在新的输入值，存储新值并进行数据提取
      console.log("New input received and stored\n\n");
      this.retrieveSearchResults(input);
      return <React.Fragment />;
    } else {
      // 数据提取完成，渲染页面
      console.log("Search result retrieved\n\n");
      console.log("Re-rendering search results\n\n");
      return (
        // 显示搜索结果
        <div id="search-results">
          {google_results.map((google_result) => (
            <div id="search-result-individual" key={google_result.position}>
              <h6 className="card-body">
                <Link
                  id="search-result-link"
                  target="_blank"
                  to={
                    "//" +
                    (google_result.link[4] === "s"
                      ? // https
                        google_result.link.slice(8, google_result.link.length)
                      : // http
                        google_result.link.slice(7, google_result.link.length))
                  }
                >
                  {google_result.title}
                </Link>
                <div
                  id="search-result-display-link"
                  className="card-subtitle mb-2 text-muted"
                >
                  {google_result.displayed_link}
                </div>
                <div>{google_result.snippet}</div>
              </h6>
              <hr styles="width:60%;" />
            </div>
          ))}
        </div>
      );
    }
  }
}

// 搜索引擎筛选
class SearchEngineFilter extends React.Component {
  // 筛选显示或隐藏谷歌搜索结果
  firefilterGoogleResultsRequest() {
    this.props.filterGoogleResults();
  }

  render() {
    return (
      <React.Fragment>
        <React.Fragment>
          <Results />
        </React.Fragment>
        <ul className="list-group list-group-flush" id="search-engine-filter">
          <li className="list-group-item" id="search-engine-filter-individual">
            <input
              type="checkbox"
              checked="checked"
              onChange={() => this.firefilterGoogleResultsRequest()}
            ></input>
            Google
          </li>
          <li className="list-group-item" id="search-engine-filter-individual">
            <input type="checkbox"></input>
            Bing
          </li>
          <li className="list-group-item" id="search-engine-filter-individual">
            <input type="checkbox"></input>
            Yahoo
          </li>
        </ul>
      </React.Fragment>
    );
  }
}

class SearchResults extends React.Component {
  render() {
    return (
      <React.Fragment>
        <SearchEngineFilter {...this.props} />
      </React.Fragment>
    );
  }
}

export default SearchResults;
